/**
 * Shape of the showplan schema metadata generated by tools/gen-showplan-schema.mjs: what .NET
 * reflection and XmlSerializer know about the classes sqltoolsservice deserializes a plan into.
 */

/** A public property of a generated class. */
export interface SchemaMember {
    /** Property name (what reflection, and so the property bag, sees). */
    name: string;
    /** Declared CLR type: "string", "bool", "int", "ulong", "double", "object", a class or enum name, with "[]" suffixes. */
    type: string;
    /** [XmlIgnore]: not read from XML ("...Specified" flags, choice identifiers). */
    ignore?: boolean;
    /** XML attribute name, for an [XmlAttribute] property. */
    attribute?: string;
    /** [XmlElement] names, with the class of each when the property is a choice group. */
    elements?: string[][];
    /** XmlElementAttribute.Order, when the class gives one. */
    order?: number;
    /** [XmlChoiceIdentifier] property name. */
    choice?: string;
    /** [XmlArray] wrapper element name, with its [XmlArrayItem] names. */
    array?: string;
    arrayItem?: string;
    arrayItemNested?: string;
    /** [XmlAnyElement] / [XmlAnyAttribute]. */
    anyElement?: boolean;
    anyAttribute?: boolean;
}

export interface SchemaClass {
    base?: string;
    members: SchemaMember[];
}
